#!/usr/bin/env python3
"""subtask1_generator.py

Deterministic JSONL event generator for AgencyBench Backend/scenario3 subtask1.

Usage
-----
    python3 subtask1_generator.py \
        --seed <int> --count <n> \
        --schema <path> --mode <append|overwrite> \
        --out data/events.jsonl

The generator is intentionally dependency free (Python 3.10 stdlib only). For a
fixed ``(seed, schema)`` pair the produced JSONL stream is byte identical: every
field (including the event id and the timestamp) is derived from a SHA-256 based
deterministic pseudo random function rather than from wall-clock time or from the
process ``random`` module.

Features
--------
* argparse entrypoint matching the required CLI contract.
* Deterministic id / timestamp synthesis (no wall clock, no unseeded RNG).
* Payload synthesis that conforms to a lightweight JSON Schema.
* Incremental ``append`` / truncating ``overwrite`` handling.
* A built-in schema validator (``--validate`` validates an existing file).
* An append-only metadata log (``logs/gen.log``) recording every invocation
  (seed, count, schema, mode, timestamp, output path and a content digest).
"""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Tuple

# --------------------------------------------------------------------------- #
# Constants
# --------------------------------------------------------------------------- #

#: Fixed reference instant so timestamps never depend on the wall clock.
FIXED_EPOCH_MS = 1_600_000_000_000  # 2020-09-13T12:26:40Z
SECOND_MS = 1_000

EVENT_TYPES = ["create", "read", "update", "delete"]
SOURCES = ["generator", "scheduler", "worker", "monitor"]
TAG_POOL = ["alpha", "beta", "gamma", "delta", "epsilon", "zeta"]

DEFAULT_SCHEMA = Path("domain") / "events.schema.json"
DEFAULT_LOG = Path("logs") / "gen.log"


# --------------------------------------------------------------------------- #
# Deterministic pseudo random helpers
# --------------------------------------------------------------------------- #


def _digest_bytes(seed: int, index: int, label: str, length: int = 32) -> bytes:
    """Return ``length`` deterministic pseudo-random bytes.

    The bytes depend only on ``(seed, index, label)`` so repeated runs with the
    same arguments always observe the same stream.  SHA-256 is used (rather than
    the ``random`` module) to guarantee stability across Python versions.
    """

    material = f"{seed}:{index}:{label}".encode("utf-8")
    out = bytearray()
    counter = 0
    while len(out) < length:
        out.extend(hashlib.sha256(material + b":" + str(counter).encode("ascii")).digest())
        counter += 1
    return bytes(out[:length])


def _rand_uint(seed: int, index: int, label: str, modulus: int) -> int:
    """Deterministic integer in ``[0, modulus)``."""

    if modulus <= 0:
        return 0
    return int.from_bytes(_digest_bytes(seed, index, label, 8), "big") % modulus


def _iso_utc(ms: int) -> str:
    """Format epoch milliseconds as an ISO-8601 UTC string (20 characters)."""

    return datetime.fromtimestamp(ms / 1000.0, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# --------------------------------------------------------------------------- #
# Event synthesis
# --------------------------------------------------------------------------- #


def _build_tags(seed: int, sequence: int) -> List[str]:
    count = _rand_uint(seed, sequence, "tag_count", 4)  # 0..3
    pool = list(TAG_POOL)
    tags: List[str] = []
    for i in range(count):
        idx = _rand_uint(seed, sequence, f"tag_{i}", len(pool))
        tags.append(pool.pop(idx))
    return tags


def build_record(seed: int, sequence: int) -> Dict[str, Any]:
    """Build one deterministic event record conforming to the event schema."""

    positive_seed = abs(int(seed)) % 100_000
    ts_ms = FIXED_EPOCH_MS + positive_seed * SECOND_MS + (sequence % 1_000_000) * SECOND_MS
    id_hash = hashlib.sha256(str(seed).encode("utf-8")).hexdigest()[:8]

    return {
        "id": f"evt-{id_hash}-{sequence:08d}",
        "timestamp": _iso_utc(ts_ms),
        "sequence": int(sequence),
        "type": EVENT_TYPES[_rand_uint(seed, sequence, "type", len(EVENT_TYPES))],
        "source": SOURCES[_rand_uint(seed, sequence, "source", len(SOURCES))],
        "payload": {
            "key": [secret redacted]
            "value": _rand_uint(seed, sequence, "value", 1_000_000),
            "checksum": hashlib.sha256(
                f"{seed}:{sequence}:checksum".encode("utf-8")
            ).hexdigest()[:16],
        },
        "tags": _build_tags(seed, sequence),
    }


def serialize(record: Dict[str, Any]) -> str:
    """Canonical, stable JSON encoding (sorted keys, compact separators)."""

    return json.dumps(record, sort_keys=[secret redacted]


# --------------------------------------------------------------------------- #
# Lightweight JSON Schema validator
# --------------------------------------------------------------------------- #


def _is_integer(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


class SchemaValidator:
    """A small JSON-Schema (draft-07 subset) validator.

    Supported keywords: [secret redacted]
    ``properties``, ``required``, ``additionalProperties`` (bool), ``items``,
    ``minItems``, ``maxItems``, ``uniqueItems``, ``minimum``, ``maximum``,
    ``exclusiveMinimum``, ``exclusiveMaximum``, ``minLength``, ``maxLength``,
    ``pattern``.
    """

    def __init__(self, schema: Any):
        self.schema = schema or {}

    def validate(self, instance: Any) -> List[str]:
        errors: List[str] = []
        self._validate(self.schema, instance, "$", errors)
        return errors

    def is_valid(self, instance: Any) -> bool:
        return not self.validate(instance)

    # -- internals --------------------------------------------------------- #

    def _validate(self, schema: Any, value: Any, path: str, errors: List[str]) -> None:
        if not isinstance(schema, dict):
            return
        if errors:  # stop early once a failure is recorded
            return

        if "const" in schema and value != schema["const"]:
            errors.append(f"{path}: expected const {schema['const']!r}")
            return

        if "enum" in schema and value not in schema["enum"]:
            errors.append(f"{path}: {value!r} not in enum")
            return

        if "type" in schema and not self._check_type(schema["type"], value):
            errors.append(f"{path}: expected type {schema['type']!r}")
            return

        if isinstance(value, dict):
            self._validate_object(schema, value, path, errors)
        if isinstance(value, list):
            self._validate_array(schema, value, path, errors)
        if _is_number(value):
            self._validate_number(schema, value, path, errors)
        if isinstance(value, str):
            self._validate_string(schema, value, path, errors)

    def _check_type(self, schema_type: Any, value: Any) -> bool:
        if isinstance(schema_type, list):
            return any(self._check_type(item, value) for item in schema_type)
        if schema_type == "object":
            return isinstance(value, dict)
        if schema_type == "array":
            return isinstance(value, list)
        if schema_type == "string":
            return isinstance(value, str)
        if schema_type == "integer":
            return _is_integer(value)
        if schema_type == "number":
            return _is_number(value)
        if schema_type == "boolean":
            return isinstance(value, bool)
        if schema_type == "null":
            return value is None
        return True

    def _validate_object(self, schema: Dict[str, Any], value: Dict[str, Any], path: str, errors: List[str]) -> None:
        for key in schema.get("required") or []:
            [secret redacted]
                errors.append(f"{path}: missing required property {key!r}")
                return

        properties = schema.get("properties") or {}
        for key, subschema in properties.items():
            [secret redacted]
                self._validate(subschema, value[key], f"{path}.{key}", errors)
                if errors:
                    return

        additional = schema.get("additionalProperties")
        if additional is False:
            for key in value:
                [secret redacted]
                    errors.append(f"{path}: additional property {key!r} not allowed")
                    return
        elif isinstance(additional, dict):
            for key, item in value.items():
                [secret redacted]
                    self._validate(additional, item, f"{path}.{key}", errors)
                    if errors:
                        return

    def _validate_array(self, schema: Dict[str, Any], value: List[Any], path: str, errors: List[str]) -> None:
        min_items = schema.get("minItems")
        max_items = schema.get("maxItems")
        if min_items is not None and len(value) < int(min_items):
            errors.append(f"{path}: fewer than {min_items} items")
            return
        if max_items is not None and len(value) > int(max_items):
            errors.append(f"{path}: more than {max_items} items")
            return
        if schema.get("uniqueItems"):
            seen = set()
            for item in value:
                marker = json.dumps(item, sort_keys=True)
                if marker in seen:
                    errors.append(f"{path}: duplicate items")
                    return
                seen.add(marker)
        items_schema = schema.get("items")
        if isinstance(items_schema, dict):
            for i, item in enumerate(value):
                self._validate(items_schema, item, f"{path}[{i}]", errors)
                if errors:
                    return

    def _validate_number(self, schema: Dict[str, Any], value: Any, path: str, errors: List[str]) -> None:
        minimum = schema.get("minimum")
        maximum = schema.get("maximum")
        exclusive_min = schema.get("exclusiveMinimum")
        exclusive_max = schema.get("exclusiveMaximum")
        if minimum is not None and value < float(minimum):
            errors.append(f"{path}: {value} < minimum {minimum}")
        elif maximum is not None and value > float(maximum):
            errors.append(f"{path}: {value} > maximum {maximum}")
        elif exclusive_min is not None and value <= float(exclusive_min):
            errors.append(f"{path}: {value} <= exclusiveMinimum {exclusive_min}")
        elif exclusive_max is not None and value >= float(exclusive_max):
            errors.append(f"{path}: {value} >= exclusiveMaximum {exclusive_max}")

    def _validate_string(self, schema: Dict[str, Any], value: str, path: str, errors: List[str]) -> None:
        min_length = schema.get("minLength")
        max_length = schema.get("maxLength")
        if min_length is not None and len(value) < int(min_length):
            errors.append(f"{path}: shorter than minLength {min_length}")
            return
        if max_length is not None and len(value) > int(max_length):
            errors.append(f"{path}: longer than maxLength {max_length}")
            return
        pattern = schema.get("pattern")
        if pattern:
            import re

            if re.search(pattern, value) is None:
                errors.append(f"{path}: does not match pattern {pattern!r}")


# --------------------------------------------------------------------------- #
# File helpers
# --------------------------------------------------------------------------- #


def load_schema(path: Path) -> Dict[str, Any]:
    raw = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError(f"Schema at {path} must be a JSON object")
    return raw


def count_lines(path: Path) -> int:
    if not path.exists():
        return 0
    total = 0
    for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
        if line.strip():
            total += 1
    return total


def sha256_file(path: Path) -> str:
    hasher = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(8192), b""):
            hasher.update(chunk)
    return hasher.hexdigest()


def append_log(log_path: Path, entry: Dict[str, Any]) -> None:
    log_path = Path(log_path)
    log_path.parent.mkdir(parents=True, exist_ok=True)
    line = f"[{entry['timestamp']}] INFO {json.dumps(entry, sort_keys=True)}"
    with log_path.open("a", encoding="utf-8", newline="\n") as handle:
        handle.write(line + "\n")


# --------------------------------------------------------------------------- #
# Core generation
# --------------------------------------------------------------------------- #


def generate(seed: int, count: int, schema_path: Path, mode: str, out_path: Path) -> Dict[str, Any]:
    schema = load_schema(schema_path)
    validator = SchemaValidator(schema)

    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)

    start_offset = 0
    if mode == "append":
        start_offset = count_lines(out_path)

    records = [build_record(seed, start_offset + i) for i in range(count)]

    invalid: List[Tuple[Dict[str, Any], List[str]]] = []
    for record in records:
        problems = validator.validate(record)
        if problems:
            invalid.append((record, problems))
    if invalid:
        first_record, first_problems = invalid[0]
        raise ValueError(
            f"generated records failed schema validation: {first_problems} "
            f"(record={serialize(first_record)})"
        )

    file_mode = "w" if mode == "overwrite" else "a"
    with out_path.open(file_mode, encoding="utf-8", newline="\n") as handle:
        for record in records:
            handle.write(serialize(record) + "\n")

    return {
        "seed": int(seed),
        "count": int(count),
        "schema": str(schema_path),
        "mode": mode,
        "out": str(out_path),
        "start_offset": start_offset,
        "total_records": count_lines(out_path),
        "sha256": sha256_file(out_path),
    }


def validate_file(schema_path: Path, out_path: Path) -> Dict[str, Any]:
    schema = load_schema(schema_path)
    validator = SchemaValidator(schema)
    valid = 0
    total = 0
    errors: List[str] = []
    out_path = Path(out_path)
    if out_path.exists():
        for line_no, line in enumerate(out_path.read_text(encoding="utf-8", errors="ignore").splitlines(), 1):
            if not line.strip():
                continue
            total += 1
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                errors.append(f"line {line_no}: invalid JSON ({exc})")
                continue
            problems = validator.validate(record)
            if problems:
                errors.append(f"line {line_no}: {'; '.join(problems)}")
            else:
                valid += 1
    return {"valid_records": valid, "total_records": total, "errors": errors}


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Deterministic JSONL event generator with a built-in schema validator.",
    )
    parser.add_argument("--seed", type=int, default=0, help="deterministic seed")
    parser.add_argument("--count", type=int, default=1, help="number of events to generate")
    parser.add_argument(
        "--schema",
        type=Path,
        default=DEFAULT_SCHEMA,
        help="path to the JSON schema describing an event",
    )
    parser.add_argument(
        "--mode",
        choices=["append", "overwrite"],
        default="overwrite",
        help="write behaviour for the output file",
    )
    parser.add_argument("--out", type=Path, default=Path("data") / "events.jsonl", help="output JSONL path")
    parser.add_argument(
        "--log",
        type=Path,
        default=DEFAULT_LOG,
        help="metadata log path (default: logs/gen.log)",
    )
    parser.add_argument(
        "--validate",
        action="store_true",
        help="validate an existing --out file against --schema instead of generating",
    )
    return parser


def main(argv: List[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    if args.count < 0:
        parser.error("--count must be non-negative")

    if args.validate:
        report = validate_file(args.schema, args.out)
        print(json.dumps(report, sort_keys=[secret redacted]
        return 0 if report["valid_records"] == report["total_records"] else 1

    try:
        entry = generate(args.seed, args.count, args.schema, args.mode, args.out)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2

    entry["timestamp"] = _iso_utc(int(datetime.now(tz=timezone.utc).timestamp() * 1000))
    append_log(args.log, entry)

    print(json.dumps(entry, sort_keys=[secret redacted]
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

