#!/usr/bin/env python3
"""Independent rubric simulation for scenario3 subtask1.

Mirrors the documented rubric:
  d = determinism (sha256 of two identical runs)
  v = valid/total records (independent validator)
  m = unique modes in logs/gen.log / 2
  g = distinct seed sample files under data/
score = round(10*(0.35d + 0.25v + 0.20m + 0.20g), 2)
"""
import hashlib
import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

SRC = Path("<workspace>")
EVAL = Path("/tmp/s1_evalspace")


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def run(cmd):
    return subprocess.run(cmd, cwd=EVAL, capture_output=True, text=True)


def valid_record(schema, obj):
    st = schema.get("type")
    if st == "object":
        if not isinstance(obj, dict):
            return False
        for k in schema.get("required", []):
            if k not in obj:
                return False
        for k, sub in (schema.get("properties") or {}).items():
            if k in obj and not valid_record(sub, obj[k]):
                return False
    elif st == "array":
        if not isinstance(obj, list):
            return False
        if "minItems" in schema and len(obj) < schema["minItems"]:
            return False
        if "maxItems" in schema and len(obj) > schema["maxItems"]:
            return False
        for it in obj:
            if not valid_record(schema.get("items", {}), it):
                return False
    elif st == "string":
        if not isinstance(obj, str):
            return False
        if "pattern" in schema and not re.search(schema["pattern"], obj):
            return False
        if "minLength" in schema and len(obj) < schema["minLength"]:
            return False
        if "maxLength" in schema and len(obj) > schema["maxLength"]:
            return False
    elif st == "integer":
        if not isinstance(obj, int) or isinstance(obj, bool):
            return False
        if "minimum" in schema and obj < schema["minimum"]:
            return False
    elif st == "number":
        if not isinstance(obj, (int, float)) or isinstance(obj, bool):
            return False
    if "enum" in schema and obj not in schema["enum"]:
        return False
    return True


def main():
    if EVAL.exists():
        shutil.rmtree(EVAL)
    EVAL.mkdir(parents=True)
    for item in SRC.iterdir():
        if item.name.startswith("."):
            continue
        if item.is_dir():
            shutil.copytree(item, EVAL / item.name)
        else:
            shutil.copy2(item, EVAL / item.name)

    schema_path = EVAL / "domain" / "events.schema.json"
    schema = json.loads(schema_path.read_text())
