#!/usr/bin/env python3
"""subtask4_planner.py

An automatic symbolic planner for scenario3.  It consumes a domain/operator JSON
description together with a goal file, searches for a feasible operator
sequence, decomposes it into a dependency DAG of tasks, exports the DAG and
writes a metrics report.

CLI
---
    python3 subtask4_planner.py \
        --domain domain/domain.json \
        --goal domain/goal.json \
        --report reports/planner_report.json \
        --plan-export data/plan_tasks.json

The report always contains the graded keys ``success_rate``, ``plan_length``,
``nodes_expanded``, ``heuristic_cost`` and ``schedule_latency``.

Planning uses A* over predicate states.  Operators are STRIPS-like
(``preconditions`` and ``effects`` with ``!p`` for deletes).  The plan is turned
into a DAG where each task depends on the earlier tasks that establish its
preconditions, guaranteeing valid, acyclic edges by construction.
"""

from __future__ import annotations

import argparse
import itertools
import heapq
import json
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple


# --------------------------------------------------------------------------- #
# Parsing helpers
# --------------------------------------------------------------------------- #


def _as_list(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    return [str(item) for item in value]


def parse_effects(raw: Any) -> Tuple[List[str], List[str]]:
    add: List[str] = []
    delete: List[str] = []
    if isinstance(raw, dict):
        add = _as_list(raw.get("add") or raw.get("adds") or raw.get("effects"))
        delete = _as_list(raw.get("del") or raw.get("delete") or raw.get("dels"))
    elif isinstance(raw, list):
        for item in raw:
            text = str(item)
            if text.startswith("!"):
                delete.append(text[1:])
            else:
                add.append(text)
    return add, delete


def parse_domain(path: Path) -> Dict[str, Any]:
    document = json.loads(Path(path).read_text(encoding="utf-8"))
    if isinstance(document, list):
        raw_operators = document
        name = "domain"
        predicates: List[str] = []
    elif isinstance(document, dict):
        raw_operators = document.get("operators") or document.get("actions") or []
        name = str(document.get("name") or "domain")
        predicates = _as_list(document.get("predicates"))
    else:
        raise ValueError("domain must be a JSON object or list")

    operators: List[Dict[str, Any]] = []
    for index, raw in enumerate(raw_operators):
        if not isinstance(raw, dict):
            continue
        preconditions = _as_list(raw.get("preconditions") or raw.get("pre") or raw.get("requires"))
        add, delete = parse_effects(raw.get("effects", raw.get("eff")))
        operators.append(
            {
                "name": str(raw.get("name") or f"op-{index:03d}"),
                "preconditions": preconditions,
                "add": add,
                "delete": delete,
                "cost": float(raw.get("cost", 1)),
                "duration": float(raw.get("duration", 0.01)),
            }
        )
    return {"name": name, "predicates": predicates, "operators": operators}


def parse_goal(path: Path) -> Dict[str, Any]:
    document = json.loads(Path(path).read_text(encoding="utf-8"))
    if isinstance(document, list):
        return {"goal": [str(item) for item in document], "init": []}
    if not isinstance(document, dict):
        raise ValueError("goal must be a JSON object or list")
    goals = document.get("goal") or document.get("goals") or document.get("target") or document.get("targets")
    init = document.get("init") or document.get("initial") or document.get("state") or []
    return {"goal": _as_list(goals), "init": _as_list(init)}


# --------------------------------------------------------------------------- #
# Search
# --------------------------------------------------------------------------- #


def preconditions_met(operator: Dict[str, Any], state: frozenset) -> bool:
    for predicate in operator["preconditions"]:
        if predicate.startswith("!"):
            if predicate[1:] in state:
                return False
        elif predicate not in state:
            return False
    return True


def apply_operator(operator: Dict[str, Any], state: frozenset) -> frozenset:
    new_state = set(state)
    for predicate in operator["add"]:
        new_state.add(predicate)
    for predicate in operator["delete"]:
        new_state.discard(predicate)
    return frozenset(new_state)


def a_star(
    operators: Sequence[Dict[str, Any]],
    init: Sequence[str],
    goals: Sequence[str],
    expansion_limit: int = 50000,
) -> Dict[str, Any]:
    start = frozenset(init)
    goal = frozenset(goals)

    def heuristic(state: frozenset) -> int:
        return len(goal - state)

    if goal <= start:
        return {"plan": [], "nodes_expanded": 0, "heuristic_cost": heuristic(start), "plan_cost": 0.0}

    counter = itertools.count()
    open_heap = [(heuristic(start), 0, next(counter), start)]
    came_from: Dict[frozenset, Tuple[Optional[frozenset], Optional[Dict[str, Any]]]] = {start: (None, None)}
    g_score: Dict[frozenset, int] = {start: 0}
    closed: set = set()
    expanded = 0

    while open_heap:
        _f, g, _tie, state = heapq.heappop(open_heap)
        if state in closed:
            continue
        closed.add(state)
        expanded += 1

        if goal <= state:
            sequence: List[Dict[str, Any]] = []
            cursor = state
            while came_from[cursor][0] is not None:
                previous, operator = came_from[cursor]
                assert operator is not None
                sequence.append(operator)
                cursor = previous  # type: ignore[assignment]
            sequence.reverse()
            return {
                "plan": sequence,
                "nodes_expanded": expanded,
                "heuristic_cost": heuristic(start),
                "plan_cost": sum(operator["cost"] for operator in sequence),
            }

        for operator in operators:
            if not preconditions_met(operator, state):
                continue
            next_state = apply_operator(operator, state)
            tentative = g + 1
            if next_state not in g_score or tentative < g_score[next_state]:
                g_score[next_state] = tentative
                came_from[next_state] = (state, operator)
                heapq.heappush(open_heap, (tentative + heuristic(next_state), tentative, next(counter), next_state))

        if expanded >= expansion_limit:
            break

    return {"plan": None, "nodes_expanded": expanded, "heuristic_cost": heuristic(start), "plan_cost": 0.0}


# --------------------------------------------------------------------------- #
# DAG construction
# --------------------------------------------------------------------------- #


def build_dag(plan: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    tasks: List[Dict[str, Any]] = []
    producer: Dict[str, int] = {}
    for index, operator in enumerate(plan):
        dependencies: List[int] = []
        for predicate in operator["preconditions"]:
            if predicate.startswith("!"):
                continue
            base = predicate
            if base in producer:
                dependencies.append(producer[base])
        dependencies = sorted(set(dependencies))
        tasks.append(
            {
                "id": f"task-{index:03d}",
                "operator": operator["name"],
                "dependencies": [f"task-{dep:03d}" for dep in dependencies],
                "estimated_duration": operator["duration"],
                "cost": operator["cost"],
            }
        )
        for predicate in operator["add"]:
            producer[predicate] = index
        for predicate in operator["delete"]:
            producer.pop(predicate, None)
    return tasks


def build_schedule(tasks: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    finish: Dict[str, float] = {}
    schedule: List[Dict[str, Any]] = []
    for task in tasks:
        start = max((finish[dep] for dep in task["dependencies"] if dep in finish), default=0.0)
        end = start + float(task.get("estimated_duration") or 0.0)
        finish[task["id"]] = end
        schedule.append({"id": task["id"], "operator": task["operator"], "start": round(start, 6), "end": round(end, 6)})
    return schedule


# --------------------------------------------------------------------------- #
# Task submission
# --------------------------------------------------------------------------- #


def submit_tasks(tasks: Sequence[Dict[str, Any]], state_dir: Path) -> Dict[str, Any]:
    """Persist the scheduled tasks through the subtask2 KV store."""

    try:
        from subtask2_kvstore import KVStore  # local import; optional dependency
    except Exception as exc:  # pragma: no cover
        return {"submitted": 0, "error": str(exc)}

    try:
        store = KVStore(state_dir, snapshot_every=0)
        task_ids = [task["id"] for task in tasks]
        store.put_committed("plan:meta", {"task_ids": task_ids, "count": len(task_ids)})
        for task in tasks:
            store.put_committed(f"plan:task:{task['id']}", dict(task))
        store.close()
        return {"submitted": len(task_ids)}
    except Exception as exc:  # pragma: no cover
        return {"submitted": 0, "error": str(exc)}


# --------------------------------------------------------------------------- #
# Planning entrypoint
# --------------------------------------------------------------------------- #


def plan(domain: Dict[str, Any], goal_spec: Dict[str, Any]) -> Dict[str, Any]:
    started = time.perf_counter()
    result = a_star(domain["operators"], goal_spec["init"], goal_spec["goal"])
    plan_operators = result["plan"]
    success = plan_operators is not None

    tasks: List[Dict[str, Any]] = build_dag(plan_operators) if success else []
    schedule = build_schedule(tasks) if success else []
    latency = time.perf_counter() - started

    edges = sum(len(task["dependencies"]) for task in tasks)
    return {
        "success": success,
        "plan": plan_operators or [],
        "tasks": tasks,
        "schedule": schedule,
        "nodes_expanded": result["nodes_expanded"],
        "heuristic_cost": result["heuristic_cost"],
        "plan_cost": result["plan_cost"],
        "length": len(plan_operators) if success else 0,
        "edges": edges,
        "schedule_latency": latency,
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="scenario3 symbolic planner")
    parser.add_argument("--domain", type=Path, required=True, help="domain/operator JSON file")
    parser.add_argument("--goal", type=Path, required=True, help="goal JSON file")
    parser.add_argument("--report", type=Path, required=True, help="metrics report JSON path")
    parser.add_argument("--plan-export", type=Path, required=True, help="plan DAG export JSON path")
    parser.add_argument("--state-dir", type=Path, default=Path("kv") / "planner", help="KV dir for task submission")
    parser.add_argument("--no-submit", action="store_true", help="skip persisting the tasks to the KV store")
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    args = build_parser().parse_args(argv)

    domain = parse_domain(args.domain)
    goal_spec = parse_goal(args.goal)
    outcome = plan(domain, goal_spec)

    task_ids = [task["id"] for task in outcome["tasks"]]
    submission: Dict[str, Any] = {"submitted": 0}
    if not args.no_submit and outcome["tasks"]:
        submission = submit_tasks(outcome["tasks"], args.state_dir)

    report = {
        "success_rate": 1.0 if outcome["success"] else 0.0,
        "plan_success": bool(outcome["success"]),
        "plan_length": outcome["length"],
        "nodes_expanded": outcome["nodes_expanded"],
        "heuristic_cost": outcome["heuristic_cost"],
        "schedule_latency": outcome["schedule_latency"],
        "plan_cost": outcome["plan_cost"],
        "edge_count": outcome["edges"],
        "task_count": len(outcome["tasks"]),
        "goal_satisfied": bool(outcome["success"]),
        "domain": str(args.domain),
        "goal": str(args.goal),
        "operators": [operator["name"] for operator in outcome["plan"]],
        "task_ids": task_ids,
        "submitted_tasks": submission.get("submitted", 0),
    }

    export = {
        "domain": domain["name"],
        "goal": goal_spec["goal"],
        "init": goal_spec["init"],
        "plan_length": outcome["length"],
        "tasks": outcome["tasks"],
        "schedule": outcome["schedule"],
    }

    args.report.parent.mkdir(parents=True, exist_ok=True)
    args.plan_export.parent.mkdir(parents=True, exist_ok=True)
    args.report.write_text(json.dumps(report, sort_keys=[secret redacted]
    args.plan_export.write_text(json.dumps(export, sort_keys=[secret redacted]

    print(json.dumps(report, sort_keys=[secret redacted]
    return 0 if outcome["success"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

