def find_domain_goal(domain_dir):
    files = sorted(p for p in domain_dir.glob("*.json") if p.is_file())
    domain = goal = None
    for path in files:
        low = path.name.lower()
        if "goal" in low and goal is None:
            goal = path
        elif "domain" in low and domain is None:
            domain = path
    if not domain and files:
        domain = files[0]
    if not goal and len(files) > 1:
        goal = files[1 if files[0] == domain else 0]
    return domain, goal


def verify_dag(plan_path):
    if not plan_path.exists():
        return 0.0
    data = json.loads(plan_path.read_text())
    tasks = data.get("tasks") if isinstance(data, dict) else data
    if not isinstance(tasks, list):
        return 0.0
    ids = {t.get("id") for t in tasks if isinstance(t, dict) and t.get("id")}
    if not ids:
        return 0.0
    graph, total_edges, valid_edges = {}, 0, 0
    for t in tasks:
        if not isinstance(t, dict):
            continue
        nid = t.get("id")
        deps = [d for d in (t.get("dependencies") or t.get("deps") or []) if isinstance(d, str)]
        if nid:
            graph[nid] = deps
        for d in deps:
            total_edges += 1
            if d in ids:
                valid_edges += 1
    visiting, visited = set(), set()

    def visit(node):
        if node in visiting:
            return False
        if node in visited:
            return True
        visiting.add(node)
        for d in graph.get(node, []):
            if d not in ids:
                continue
            if not visit(d):
                return False
        visiting.remove(node)
        visited.add(node)
        return True

    if not all(visit(n) for n in ids):
        return 0.0
    if total_edges == 0:
        return 1.0
    return clamp(valid_edges / total_edges)


def main():
