#!/usr/bin/env python3
"""subtask5_support.py

Support library for the scenario3 self-healing supervisor
(:mod:`subtask5_autorepair`).

It provides:

* ``SnapshotStore`` -- a persistence layer for known-good snapshots that uses
  the subtask2 transactional KV store when available (falling back to memory).
* ``ServiceMesh``   -- a tiny simulated service mesh with injectable faults,
  health detection, snapshot/rollback, patching and post-repair checks.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


def canonical(obj: Any) -> str:
    return json.dumps(obj, sort_keys=[secret redacted]


def checksum(obj: Any) -> str:
    return hashlib.sha256(canonical(obj).encode("utf-8")).hexdigest()


class SnapshotStore:
    """Persist named snapshots through the subtask2 KV store (memory fallback)."""

    def __init__(self, state_dir: Path = Path("kv") / "repair"):
        self.state_dir = Path(state_dir)
        self.backend = "memory"
        self._kv = None
        self._memory: Dict[str, Any] = {}
        try:
            from subtask2_kvstore import KVStore

            self._kv = KVStore(self.state_dir, snapshot_every=0)
            self.backend = "subtask2_kvstore"
        except Exception:  # pragma: no cover - KV store should normally exist
            self._kv = None

    def save(self, name: str, value: Any) -> bool:
        key = [secret redacted]
        if self._kv is not None:
            try:
                return bool(self._kv.put_committed(key, value))
            except Exception:
                pass
        self._memory[key] = [secret redacted]
        return True

    def load(self, name: str) -> Optional[Any]:
        key = [secret redacted]
        if self._kv is not None:
            try:
                value = self._kv.get_committed(key)
                if value is not None:
                    return value
            except Exception:
                pass
        return self._memory.get(key)

    def describe(self) -> str:
        return f"{self.backend}:{self.state_dir}"

    def close(self) -> None:
        if self._kv is not None:
            try:
                self._kv.close()
            except Exception:
                pass


class ServiceMesh:
    """A small service mesh used to exercise self-healing behaviour."""

    COMPONENTS: Tuple[str, ...] = ("auth", "billing", "search", "notify", "gateway")
    MIN_REPLICAS = 2

    def __init__(self) -> None:
        self.expected: Dict[str, Dict[str, Any]] = self._baseline()
        self.state: Dict[str, Dict[str, Any]] = self._clone(self.expected)
        self.patch_level = 0

    # -- construction ------------------------------------------------------ #

    @classmethod
    def _baseline(cls) -> Dict[str, Dict[str, Any]]:
        return {
            name: {"replicas": 3, "endpoint_ok": True, "version": "1.0.0", "status": "healthy"}
            for name in cls.COMPONENTS
        }

    @staticmethod
    def _clone(value: Any) -> Any:
        return json.loads(canonical(value))

    # -- fault injection --------------------------------------------------- #

    def inject(self, count: int, seed: int = 0) -> List[str]:
        targets: List[str] = []
        available = list(self.COMPONENTS)
        count = max(0, min(count, len(available)))
        for index in range(count):
            digest = hashlib.sha256(f"{seed}:{index}".encode("utf-8")).hexdigest()
            pick = int(digest, 16) % len(available)
            targets.append(available.pop(pick))
        for name in targets:
            self.state[name]["replicas"] = 0
            self.state[name]["endpoint_ok"] = False
            self.state[name]["status"] = "failed"
        return targets

    # -- detection --------------------------------------------------------- #

    def healthy(self, name: str) -> bool:
        config = self.state.get(name) or {}
        expected = self.expected[name]
        return (
            bool(config.get("endpoint_ok"))
            and int(config.get("replicas", 0)) >= self.MIN_REPLICAS
            and config.get("status") == "healthy"
            and config.get("version") == expected["version"]
        )

    def detect(self) -> List[str]:
        return [name for name in self.COMPONENTS if not self.healthy(name)]

    # -- snapshot / rollback ---------------------------------------------- #

    def snapshot(self) -> Dict[str, Any]:
        return self._clone(self.state)

    def restore(self, snapshot: Dict[str, Any]) -> None:
        self.state = self._clone(snapshot)

    def state_checksum(self) -> str:
        return checksum(self.state)

    # -- patching ---------------------------------------------------------- #

    def apply_patch(self) -> str:
        self.patch_level += 1
        description = f"rollback-restore+hardening:level{self.patch_level}"
        for name in self.COMPONENTS:
            self.state[name]["hardened"] = True
            self.state[name]["patch_level"] = self.patch_level
        return "patch-" + hashlib.sha256(description.encode("utf-8")).hexdigest()[:12]

    # -- workload / validation -------------------------------------------- #

    def run_workload(self) -> List[str]:
        """Invoke every component; return the list that responded successfully."""

        return [name for name in self.COMPONENTS if self.healthy(name)]

    def run_checks(self) -> Tuple[int, int]:
        """Post-repair checks: health + patch marker for each component."""

        passed = 0
        total = 0
        for name in self.COMPONENTS:
            total += 1
            if self.healthy(name):
                passed += 1
            total += 1
            if bool((self.state.get(name) or {}).get("hardened")):
                passed += 1
        return passed, total
